           <div>
             <p class="eyebrow">Featured products</p>
             <h2 id="featured-products-heading">Best sellers in the spotlight</h2>
           </div>
           <a href="/collections/featured" class="button-secondary">View full collection</a>
         </div>
         <div class="grid-3">
           ${featuredProducts.map((product) => `
             <article class="product-card">
               <div class="card-visual" aria-hidden="true" style="background-image: linear-gradient(135deg, ${escapeHtml(product.tone)}, rgba(16, 29, 56, 0.38));"></div>
               <div class="card-content">
                 <span class="chip">${escapeHtml(product.category)}</span>
                 <a href="${escapeHtml(product.href)}" aria-label="View product: ${escapeHtml(product.name)}">
                   <h3>${escapeHtml(product.name)}</h3>
                 </a>
                 <p>${escapeHtml(product.detail)}</p>
                 <div class="price-row">
                   <span class="price">${escapeHtml(product.price)}</span>
                   <span class="compare">${escapeHtml(product.compareAt)}</span>
                 </div>
               </div>
               <div class="card-actions">
                 <button class="button" type="button" data-product="${escapeHtml(product.name)}" aria-label="Add to bag: ${escapeHtml(product.name)}">Add to bag</button>
                 <button class="button-secondary" type="button" data-save="${escapeHtml(product.name)}" aria-label="Save for later: ${escapeHtml(product.name)}">Save for later</button>
               </div>
             </article>
           `).join("")}
         </div>
       </section>
     `;

     const Deals = () => `
       <section id="deals" class="section-block panel" aria-labelledby="deals-heading">
         <div class="section-header">
           <div>
             <p class="eyebrow">Deals</p>
             <h2 id="deals-heading">Offers worth catching before midnight</h2>
           </div>
           <p>Smart savings on premium pieces without losing the luxury feel.</p>
         </div>
         <div class="grid-2">
           ${deals.map((deal) => `
             <article class="deal-card">
               <span class="chip">${escapeHtml(deal.tag)}</span>
               <h3>${escapeHtml(deal.title)}</h3>
               <p>${escapeHtml(deal.summary)}</p>
               <div class="card-actions">
                 <a class="button" href="${escapeHtml(deal.href)}">Claim offer</a>
                 <a class="button-secondary" href="#featured-products">Browse qualifying items</a>
               </div>
             </article>
           `).join("")}
         </div>
       </section>
     `;

     const Editorial = () => `
       <section id="editorial" class="section-block panel" aria-labelledby="editorial-heading">
         <div class="section-header">
           <div>
             <p class="eyebrow">Editorial content</p>
             <h2 id="editorial-heading">Stories that shape the season</h2>
           </div>
           <p>Guides, inspiration, and behind-the-scenes notes that deepen the retail experience.</p>
         </div>
         <div class="grid-3">
           ${stories.map((story) => `
             <article class="story-card">
               <div class="card-visual ${escapeHtml(story.styleClass)}" aria-hidden="true"></div>
               <div class="card-content">
                 <h3>${escapeHtml(story.title)}</h3>
                 <p>${escapeHtml(story.description)}</p>
               </div>
               <a class="button-secondary" href="${escapeHtml(story.href)}">${escapeHtml(story.cta)}</a>
             </article>
           `).join("")}
         </div>
       </section>
     `;

     const Footer = () => `
       <footer class="site-footer">
         <div class="footer-grid">
           <section aria-labelledby="footer-about-heading">
             <h2 id="footer-about-heading">Northstar Mercantile</h2>
             <p>
               A modern retail brand pairing premium essentials with editorial storytelling, seasonal drops, and
               practical service.
             </p>
             <p id="status-message" class="status" aria-live="polite"></p>
           </section>
           <nav aria-labelledby="footer-support">
             <h2 id="footer-support">Customer care</h2>
             <ul>
               <li><a href="#">Shipping and returns</a></li>
               <li><a href="#">Store locator</a></li>
               <li><a href="#">Gift cards</a></li>
             </ul>
           </nav>
           <nav aria-label="Footer">
             <h2>About</h2>
             <ul>
               <li><a href="#">Our story</a></li>
               <li><a href="#">Journal archive</a></li>
               <li><a href="#">Careers</a></li>
             </ul>
           </nav>
         </div>
       </footer>
     `;

     const App = () => `
       ${Header()}
       <div class="page-shell">
         <main id="maincontent" tabindex="-1">
           ${Hero()}
           ${FeaturedProducts()}
           ${Deals()}
           ${Editorial()}
         </main>
       </div>
       ${Footer()}
     `;

     document.getElementById("app").innerHTML = App();

     const statusMessage = document.getElementById("status-message");
     document.querySelectorAll("[data-product]").forEach((button) => {
       button.addEventListener("click", () => {
         statusMessage.textContent = `${button.dataset.product} added to bag.`;
       });
     });
     document.querySelectorAll("[data-save]").forEach((button) => {
       button.addEventListener("click", () => {
         statusMessage.textContent = `${button.dataset.save} saved for later.`;
       });
     });
   </script>
 </body>
 </html>

')
